// Check Clojure's areas against the other shape notebooks (if you ran them).
const clj = nb.get('areas_clj');
if (!clj) return 'Run the first Clojure cell (the slow one) first.';

console.log('clojure computed:', clj.map(s => s.name + '=' + s.area).join('  '));

const java = nb.get('areas_java');
if (java) {
  const agree = clj.every(c => {
    const j = java.find(x => x.name === c.name);
    return j && Math.abs(j.area - c.area) < 1e-3;
  });
  console.log('matches the Java notebook results:', agree);
}
return clj;
